function abbreviateProduct(left: number, right: number): string {
    const LIMIT = 1e12; // keep only enough digits for prefix/suffix logic
    let logSum = 0;
    let twos = 0;
    let fives = 0;

    let suffix = 1n; // product with 2/5 factors stripped, kept modulo 1e12
    const MOD = 1000000000000n; // 1e12

    for (let x = left; x <= right; x++) {
        let y = x;
        logSum += Math.log10(y);

        while (y % 2 === 0) {
            twos++;
            y /= 2;
        }
        while (y % 5 === 0) {
            fives++;
            y /= 5;
        }

        suffix = (suffix * BigInt(y)) % MOD;
    }

    const zeros = Math.min(twos, fives);

    // Reinsert extra 2s or 5s after removing trailing zeros
    let extra2 = twos - zeros;
    let extra5 = fives - zeros;

    while (extra2-- > 0) suffix = (suffix * 2n) % MOD;
    while (extra5-- > 0) suffix = (suffix * 5n) % MOD;

    const digits = Math.floor(logSum) + 1 - zeros;

    let suffixStr = suffix.toString();
    // remove leading zeros from the preserved suffix
    suffixStr = suffixStr.replace(/^0+/, "");
    if (suffixStr === "") suffixStr = "0";

    if (digits <= 10) {
        // Exact number fits in at most 10 digits, so suffix contains it fully
        return `${suffixStr}e${zeros} `;
    }

    // Need first 5 and last 5 digits
    const frac = logSum - Math.floor(logSum);
    const first = Math.floor(Math.pow(10, frac + 4)); // 5 leading digits of product before removing zeros
    const firstStr = first.toString();

    const last5 = suffix.toString().padStart(5, "0").slice(-5);

    return `${firstStr}...${last5}e${zeros} `;
};
