function maxScore(nums: number[]): number {
    const m = nums.length;
    const full = (1 << m) - 1;

    const gcd = (a: number, b: number): number => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const pairGcd: number[][] = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            pairGcd[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const dp = new Array<number>(1 << m).fill(0);

    for (let mask = 0; mask <= full; mask++) {
        const used = countBits(mask);
        if (used % 2 === 1) continue;
        const op = used / 2 + 1;
        if (mask === full) continue;

        let first = 0;
        while (((mask >> first) & 1) === 1) first++;

        for (let j = first + 1; j < m; j++) {
            if (((mask >> j) & 1) === 0) {
                const nextMask = mask | (1 << first) | (1 << j);
                dp[nextMask] = Math.max(dp[nextMask], dp[mask] + op * pairGcd[first][j]);
            }
        }
    }

    return dp[full];

    function countBits(x: number): number {
        let c = 0;
        while (x) {
            x &= x - 1;
            c++;
        }
        return c;
    }
}
