function maxEqualFreq(nums: number[]): number {
    const cnt = new Map<number, number>(); // number -> frequency
    const freq = new Map<number, number>(); // frequency -> how many numbers have this frequency
    let ans = 0;
    let maxF = 0;

    const getFreqCount = (f: number): number => freq.get(f) ?? 0;
    const setFreqCount = (f: number, v: number) => {
        if (v === 0) freq.delete(f);
        else freq.set(f, v);
    };

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        const oldF = cnt.get(x) ?? 0;
        const newF = oldF + 1;
        cnt.set(x, newF);

        if (oldF > 0) setFreqCount(oldF, getFreqCount(oldF) - 1);
        setFreqCount(newF, getFreqCount(newF) + 1);

        if (newF > maxF) maxF = newF;

        const len = i + 1;
        const cMax = getFreqCount(maxF);
        const c1 = getFreqCount(1);
        const cMaxMinus1 = getFreqCount(maxF - 1);

        // Case 1: all numbers appear once
        if (maxF === 1) {
            ans = len;
        }
        // Case 2: one number appears once, all others appear maxF times
        else if (c1 === 1 && cMax * maxF + 1 === len) {
            ans = len;
        }
        // Case 3: one number appears maxF times, all others appear maxF-1 times
        else if (cMax === 1 && cMax * maxF + cMaxMinus1 * (maxF - 1) === len && cMaxMinus1 > 0) {
            ans = len;
        }
        // Simpler equivalent checks:
        // - exactly one frequency 1 and rest maxF
        // - exactly one frequency maxF and rest maxF-1
        // The above conditions cover them.

        // More robust general checks for standard known cases
        if (
            maxF === 1 ||
            (c1 === 1 && cMax * maxF + 1 === len) ||
            (cMax === 1 && cMax * maxF + cMaxMinus1 * (maxF - 1) === len && cMaxMinus1 > 0)
        ) {
            ans = len;
        }
    }

    return ans;
};
