function maximumBeauty(flowers: number[], newFlowers: number, target: number, full: number, partial: number): number {
    const n = flowers.length;
    const arr = flowers.slice().sort((a, b) => a - b);

    let left = 0;
    let right = n;
    while (left < right) {
        const mid = (left + right) >> 1;
        if (arr[mid] >= target) right = mid;
        else left = mid + 1;
    }
    const initialFull = n - left;

    const less = arr.slice(0, left).map(v => Math.min(v, target));
    const m = less.length;
    if (m === 0) return initialFull * full;

    const prefix: bigint[] = new Array(m + 1);
    prefix[0] = 0n;
    for (let i = 0; i < m; i++) prefix[i + 1] = prefix[i] + BigInt(less[i]);

    const needToMake = (k: number): bigint => {
        if (k <= 0) return 0n;
        return BigInt(k) * BigInt(target) - (prefix[m] - prefix[m - k]);
    };

    let ans = 0n;
    let low = 0, high = m;
    const nf = BigInt(newFlowers);
    const tgt = BigInt(target);
    const p = BigInt(partial);
    const f = BigInt(full);

    for (let fullCnt = 0; fullCnt <= initialFull; fullCnt++) {
        const remainFull = initialFull - fullCnt;
        const budget = nf - BigInt(fullCnt) * tgt;
        if (budget < 0n) break;

        const incompleteCnt = m - remainFull;
        let bestMin = 0n;

        if (incompleteCnt > 0) {
            const limit = m - remainFull;
            let l = 0, r = limit;
            while (l < r) {
                const mid = ((l + r + 1) >> 1);
                if (needToMake(mid) <= budget) l = mid;
                else r = mid - 1;
            }
            if (l > 0) {
                const used = needToMake(l);
                const remain = budget - used;
                const val = BigInt(less[l - 1]) + remain / BigInt(l);
                bestMin = val < tgt ? val : (tgt - 1n);
            }
        }

        const beauty = BigInt(fullCnt) * f + bestMin * p;
        if (beauty > ans) ans = beauty;
    }

    return Number(ans);
};

