function minMalwareSpread(graph: number[][], initial: number[]): number {
    const n = graph.length;
    initial.sort((a, b) => a - b);

    const infected = new Array<boolean>(n).fill(false);
    for (const x of initial) infected[x] = true;

    const compId = new Array<number>(n).fill(-1);
    const compSize: number[] = [];
    const compInfectedCount: number[] = [];

    let cid = 0;
    const queue: number[] = [];

    for (let i = 0; i < n; i++) {
        if (compId[i] !== -1) continue;
        let head = 0;
        queue.length = 0;
        queue.push(i);
        compId[i] = cid;
        let size = 0;
        let infCount = 0;

        while (head < queue.length) {
            const u = queue[head++];
            size++;
            if (infected[u]) infCount++;

            for (let v = 0; v < n; v++) {
                if (graph[u][v] === 1 && compId[v] === -1) {
                    compId[v] = cid;
                    queue.push(v);
                }
            }
        }

        compSize.push(size);
        compInfectedCount.push(infCount);
        cid++;
    }

    const save = new Array<number>(n).fill(0);

    for (const node of initial) {
        const c = compId[node];
        if (compInfectedCount[c] === 1) {
            save[node] = compSize[c];
        }
    }

    let ans = initial[0];
    for (const node of initial) {
        if (save[node] > save[ans] || (save[node] === save[ans] && node < ans)) {
            ans = node;
        }
    }

    return ans;
};
