    const letters = Array.from(chars);
    const idx = new Map<string, number>();
    for (let i = 0; i < letters.length; i++) idx.set(letters[i], i);

    const n = letters.length;
    const assign = new Array<number>(n).fill(-1);
    const used = new Array<boolean>(10).fill(false);

    const maxLen = Math.max(result.length, ...words.map(w => w.length));

