function numSmallerByFrequency(queries: string[], words: string[]): number[] {
    const freq = (s: string): number => {
        let minChar = 'z';
        let count = 0;
        for (const ch of s) {
            if (ch < minChar) {
                minChar = ch;
                count = 1;
            } else if (ch === minChar) {
                count++;
            }
        }
        return count;
    };

    const wordFreqs = words.map(freq).sort((a, b) => a - b);

    const upperBound = (arr: number[], target: number): number => {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] <= target) l = m + 1;
            else r = m;
        }
        return l;
    };

    return queries.map(q => {
        const fq = freq(q);
        const idx = upperBound(wordFreqs, fq);
        return wordFreqs.length - idx;
    });
};

