function maximumBinaryString(binary: string): string {
    const n = binary.length;
    let zeroCount = 0;
    let firstZero = -1;

    for (let i = 0; i < n; i++) {
        if (binary[i] === '0') {
            zeroCount++;
            if (firstZero === -1) firstZero = i;
        }
    }

    if (zeroCount <= 1) return binary;

    const zeroPos = firstZero + zeroCount - 1;
    let res = '1'.repeat(n);
    res = res.slice(0, zeroPos) + '0' + res.slice(zeroPos + 1);
    return res;
};
