function minAreaRect(points: number[][]): number {
    const cols = new Map<number, number[]>();
    for (const [x, y] of points) {
        if (!cols.has(x)) cols.set(x, []);
        cols.get(x)!.push(y);
    }

    const xVals = Array.from(cols.keys()).sort((a, b) => a - b);
    for (const x of xVals) cols.get(x)!.sort((a, b) => a - b);

    const lastSeen = new Map<string, number>();
    let ans = Number.POSITIVE_INFINITY;

    for (let i = 0; i < xVals.length; i++) {
        const x1 = xVals[i];
        const ys1 = cols.get(x1)!;
        for (let a = 0; a < ys1.length; a++) {
            for (let b = a + 1; b < ys1.length; b++) {
                const y1 = ys1[a], y2 = ys1[b];
                const key = `${y1},${y2}`;
                if (lastSeen.has(key)) {
