    const n = slices.length;
    const choose = Math.floor(n / 3);

    function solve(arr: number[]): number {
        const m = arr.length;
        const dp = Array.from({ length: m + 1 }, () => new Array(choose + 1).fill(0));

        for (let i = 1; i <= m; i++) {
            const val = arr[i - 1];
            const limit = Math.min(choose, Math.floor((i + 1) / 2));
            for (let j = 1; j <= limit; j++) {
