            for (let j = limit + 1; j <= choose; j++) {
                dp[i][j] = dp[i - 1][j];
            }
        }

        return dp[m][choose];
    }

    const case1 = solve(slices.slice(0, n - 1));
    const case2 = solve(slices.slice(1));
    return Math.max(case1, case2);
