function regionsBySlashes(grid: string[]): number {
    const n = grid.length;
    const size = n * n * 4;
    const parent = new Array<number>(size);
    const rank = new Array<number>(size).fill(0);

    for (let i = 0; i < size; i++) parent[i] = i;

    const find = (x: number): number => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (a: number, b: number): void => {
        let pa = find(a), pb = find(b);
        if (pa === pb) return;
        if (rank[pa] < rank[pb]) {
            parent[pa] = pb;
        } else if (rank[pa] > rank[pb]) {
            parent[pb] = pa;
        } else {
            parent[pb] = pa;
            rank[pa]++;
        }
    };

    const idx = (r: number, c: number, k: number) => ((r * n + c) * 4 + k);

    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            const ch = grid[r][c];
            const base = idx(r, c, 0);

            if (ch === ' ') {
                union(base + 0, base + 1);
                union(base + 1, base + 2);
                union(base + 2, base + 3);
            } else if (ch === '/') {
                union(base + 0, base + 3);
                union(base + 1, base + 2);
            } else { // '\\'
                union(base + 0, base + 1);
                union(base + 2, base + 3);
            }

            if (r + 1 < n) {
                union(base + 2, idx(r + 1, c, 0));
            }
            if (c + 1 < n) {
                union(base + 1, idx(r, c + 1, 3));
            }
        }
    }

    let count = 0;
    for (let i = 0; i < size; i++) {
        if (find(i) === i) count++;
    }
    return count;
};
