            else rightRemove++;
        }
    }

    const res = new Set<string>();
    const n = s.length;

    function dfs(index: number, leftCount: number, rightCount: number, lRem: number, rRem: number, path: string[]): void {
        if (index === n) {
            if (lRem === 0 && rRem === 0 && leftCount === rightCount) {
                res.add(path.join(''));
            }
