        }

        const ch = s[index];

        if (ch === '(') {
            if (lRem > 0) dfs(index + 1, leftCount, rightCount, lRem - 1, rRem, path);
            path.push(ch);
            dfs(index + 1, leftCount + 1, rightCount, lRem, rRem, path);
            path.pop();
        } else if (ch === ')') {
            if (rRem > 0) dfs(index + 1, leftCount, rightCount, lRem, rRem - 1, path);
