function isScramble(s1: string, s2: string): boolean {
    const n = s1.length;
    if (n !== s2.length) return false;
    if (s1 === s2) return true;

    const memo = new Map<string, boolean>();

    const sameCount = (aL: number, bL: number, len: number): boolean => {
        const cnt = new Int16Array(26);
        for (let i = 0; i < len; i++) {
            cnt[s1.charCodeAt(aL + i) - 97]++;
            cnt[s2.charCodeAt(bL + i) - 97]--;
        }
        for (let i = 0; i < 26; i++) {
            if (cnt[i] !== 0) return false;
        }
        return true;
    };

    const dfs = (aL: number, bL: number, len: number): boolean => {
        const key = `${aL},${bL},${len}`;
        const cached = memo.get(key);
        if (cached !== undefined) return cached;

        if (s1.slice(aL, aL + len) === s2.slice(bL, bL + len)) {
            memo.set(key, true);
            return true;
        }

        if (!sameCount(aL, bL, len)) {
            memo.set(key, false);
            return false;
        }

        for (let k = 1; k < len; k++) {
            if (
