function shiftGrid(grid: number[][], k: number): number[][] {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    k %= total;
    if (k === 0) return grid.map(row => row.slice());

    const res: number[][] = Array.from({ length: m }, () => Array(n));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const idx = i * n + j;
            const newIdx = (idx + k) % total;
            const ni = Math.floor(newIdx / n);
            const nj = newIdx % n;
            res[ni][nj] = grid[i][j];
        }
    }
    return res;
};
