function sortByBits(arr: number[]): number[] {
    const bitCount = (x: number): number => {
        let count = 0;
        while (x > 0) {
            x &= x - 1;
            count++;
        }
        return count;
    };

    return arr.sort((a, b) => {
        const ca = bitCount(a);
        const cb = bitCount(b);
        if (ca !== cb) return ca - cb;
        return a - b;
    });
};
