function minStickers(stickers: string[], target: string): number {
    const m = target.length;
    const targetChars = target.split("");
    const stickerCounts: number[][] = stickers.map(s => {
        const cnt = new Array(26).fill(0);
        for (const ch of s) cnt[ch.charCodeAt(0) - 97]++;
        return cnt;
    });

    const memo = new Map<string, number>();
    memo.set("", 0);

    function helper(rem: string): number {
        if (memo.has(rem)) return memo.get(rem)!;

        const need = new Array(26).fill(0);
        for (const ch of rem) need[ch.charCodeAt(0) - 97]++;

        let ans = Number.MAX_SAFE_INTEGER;
        const first = rem.charCodeAt(0) - 97;

        for (const sc of stickerCounts) {
            if (sc[first] === 0) continue;

            let next = "";
            for (let i = 0; i < 26; i++) {
                const left = need[i] - sc[i];
                for (let k = 0; k < left; k++) {
                    next += String.fromCharCode(97 + i);
                }
            }

            const sub = helper(next);
            if (sub !== -1) ans = Math.min(ans, 1 + sub);
        }

        const res = ans === Number.MAX_SAFE_INTEGER ? -1 : ans;
        memo.set(rem, res);
        return res;
    }

    const sortedTarget = targetChars.sort().join("");
    return helper(sortedTarget);
};
