function isMatch(s: string, p: string): boolean {
    const m = s.length, n = p.length;

    // Collapse consecutive '*' to one '*'
    let np = "";
    for (let i = 0; i < n; i++) {
        if (p[i] === '*' && np.length > 0 && np[np.length - 1] === '*') continue;
        np += p[i];
    }
    p = np;

    const nn = p.length;
    let prev = new Array<boolean>(nn + 1).fill(false);
    prev[0] = true;

    for (let j = 1; j <= nn; j++) {
        prev[j] = prev[j - 1] && p[j - 1] === '*';
    }

    for (let i = 1; i <= m; i++) {
        const cur = new Array<boolean>(nn + 1).fill(false);
        for (let j = 1; j <= nn; j++) {
            const pc = p[j - 1];
            if (pc === '*') {
                cur[j] = cur[j - 1] || prev[j];
            } else if (pc === '?' || pc === s[i - 1]) {
                cur[j] = prev[j - 1];
            }
        }
        prev = cur;
    }

    return prev[nn];
};
